import { E, P, alpha, clamp, defineComponent, mix, pr } from "@motioneasy/engine";
import { stage, style } from "../kit";

type Props = { headline: string; sub: string; sweep: number; angle: number; size: number; font: string; weight: number };

const START = 0.5;

export default defineComponent<Props>({
  id: "light-sweep",
  name: "Light Sweep",
  version: "1.0.0",
  group: "elements",
  category: "text-reveals",
  description: "Type waits in the dark, barely embossed. A band of light sweeps across and leaves every letter lit, with a soft specular edge.",
  tags: ["light", "reveal", "premium", "dark", "glow"],
  added: "2026-10-03",
  featured: true,
  theme: { mode: "dark", lighting: 0.7, grain: 0.4, vignette: 0.6 },
  notes: "One sweep per video, on the hero line (motion law Q4). Pairs with a slow, low music bed.",
  params: {
    headline: P.text("Made to *glow.*", "Headline", { multiline: true, maxLength: 60 }),
    sub: P.text("Cinematic captions, rendered on your machine.", "Subline", { maxLength: 90 }),
    sweep: P.number(1.6, "Sweep time", { min: 0.6, max: 4, step: 0.1, unit: "s" }),
    angle: P.number(18, "Sweep angle", { min: -40, max: 40, step: 1, unit: "°", group: "style" }),
    size: P.number(1, "Type size", { min: 0.6, max: 1.4, step: 0.05, group: "style" }),
    font: P.font("brand", "Typeface"),
    weight: P.number(800, "Weight", { min: 300, max: 800, step: 50, group: "style" }),
  },
  duration: (p) => START + p.sweep + 2,
  poster: 0.8,
  sounds: (p) => [
    { at: 0.05, sound: "riser.air", len: START + p.sweep * 0.5, gain: 0.45, role: "breath" },
    { at: START + p.sweep * 0.15, sound: "whoosh.deep", gain: 0.5, role: "sweep" },
    { at: START + p.sweep * 0.7, sound: "tonal.shimmer", gain: 0.35, role: "glint" },
  ],
  render(c, p) {
    const T = c.theme;
    const t = c.t;
    const center = true;
    const st = style(c, (c.vertical ? 190 : 180) * p.size, { fontParam: p.font, weight: p.weight, lineHeight: 1.0 });
    const L = c.fit(p.headline, st, c.safe.w * 0.9, c.safe.h * 0.42, { align: "center" });
    const ox = c.cx - L.width / 2;
    const oy = c.cy - L.height / 2 - (p.sub ? L.size * 0.25 : 0);
    const u = pr(t, START, START + p.sweep, E.inOut);
    const band = Math.max(L.width * 0.35, 260);
    // Sweep position across the text block, from beyond the left edge to beyond the right.
    const sx = ox - band + u * (L.width + band * 2);
    stage(c, { kind: "soft", focus: [clamp(sx, ox, ox + L.width), oy + L.height / 2], flare: Math.sin(Math.PI * u) * 0.6 });
    const push = 1 + 0.035 * E.cine(c.p);
    c.with({ x: c.cx, y: c.cy, scale: push }, () => {
      c.translate(-c.cx, -c.cy);
      // 1. Dormant type: a faint emboss.
      c.drawLayout(L, ox, oy + 1.5, { color: alpha("#000000", 0.5) });
      c.drawLayout(L, ox, oy, { color: alpha(T.fg, 0.07) });
      // 2. Lit type, revealed by a gradient mask that trails the band.
      const tan = Math.tan((p.angle * Math.PI) / 180);
      const lit = c.layer(c.W, c.H, (lc) => {
        lc.drawLayout(L, ox, oy, { color: T.fg, emColor: T.accent, glow: T.mode === "dark" ? { color: mix(T.glow, T.bg, 0.3), blur: 34, strength: 0.6 } : undefined });
        lc.blend("destination-in");
        lc.save();
        lc.ctx.transform(1, 0, -tan, 1, tan * (oy + L.height / 2), 0);
        const g = lc.linear(sx - band, 0, sx + band * 0.6, 0, [[0, "#000"], [0.62, "#000"], [1, "rgba(0,0,0,0)"]]);
        lc.rect(-c.W, 0, c.W * 3, c.H, g);
        lc.restore();
      });
      c.drawLayer(lit, 0, 0);
      // 3. Specular edge: a bright narrow band clipped to the letters.
      const spec = c.layer(c.W, c.H, (lc) => {
        lc.drawLayout(L, ox, oy, { color: "#FFFFFF" });
        lc.blend("destination-in");
        lc.save();
        lc.ctx.transform(1, 0, -tan, 1, tan * (oy + L.height / 2), 0);
        lc.rect(-c.W, 0, c.W * 3, c.H, lc.linear(sx - band * 0.25, 0, sx + band * 0.6, 0, [[0, "rgba(0,0,0,0)"], [0.62, "#000"], [1, "rgba(0,0,0,0)"]]));
        lc.restore();
      });
      c.drawLayer(spec, 0, 0, { alpha: Math.sin(Math.PI * u) * 0.9, blend: "screen" });
      if (p.sub) {
        const S = c.fit(p.sub, style(c, Math.max(30, L.size * 0.24), { fontParam: p.font, weight: 500, lineHeight: 1.3, tracking: -0.005 }), c.safe.w * 0.8, L.size, { align: "center" });
        const v = pr(t, START + p.sweep * 0.75, START + p.sweep * 0.75 + 0.9, E.out);
        c.drawLayout(S, c.cx - S.width / 2, oy + L.height + L.size * 0.5 + (1 - v) * 14, { color: T.soft, alpha: v });
      }
    });
    void center;
  },
});

logo-bars.code:
import { E, P, alpha, defineComponent, kf, pr, spring, SPRING, type Key } from "@motioneasy/engine";
import { stage, style } from "../kit";
import { BRAND } from "../demo";

type Props = { wordmark: string | null; bars: number; colors: string[]; tagline: string; font: string };

// Real CaptionsEasy mark geometry (sources/brand/captionseasy-logo.svg): three rounded bars.
const BAR_W = 15.63, BAR_GAP = 25.68 - 15.63;
const HEIGHTS = [53.6, 89.33, 71.46];

export default defineComponent<Props>({
  id: "logo-bars",
  name: "Equalizer Sting",
  version: "1.0.0",
  group: "elements",
  category: "logos",
  description: "The mark's bars bounce like a voice meter, settle into the logo shape, then slide left as the wordmark wipes out from behind them.",
  tags: ["logo", "audio", "bars", "sting", "captionseasy"],
  added: "2026-10-03",
  featured: false,
  theme: { mode: "light", lighting: 0.6, grain: 0.3, vignette: 0.25 },
  notes: "Built on the CaptionsEasy mark (three bars). Swap the wordmark file for another bar-based mark.",
  params: {
    wordmark: P.media(BRAND.wordmark, "Wordmark", "image"),
    bars: P.number(3, "Bars", { min: 3, max: 3, step: 1, advanced: true }),
    colors: P.list(["#1A1A1A", "#1A1A1A", "#1A1A1A"], "Bar colours", { min: 3, max: 3, help: "Hex colours for the three bars." }),
    tagline: P.text("Stop timing captions.", "Tagline", { maxLength: 60 }),
    font: P.font("brand", "Typeface"),
  },
  duration: 4.4,
  poster: 0.75,
  sounds: () => [
    { at: 0.1, sound: "ui.pop", gain: 0.4, role: "bar" },
    { at: 0.22, sound: "ui.pop", gain: 0.37, seed: 2, role: "bar" },
    { at: 0.34, sound: "ui.pop", gain: 0.34, role: "bar" },
    { at: 1.55, sound: "whoosh.swipe", gain: 0.5, role: "slide" },
    { at: 1.95, sound: "impact.land", gain: 0.5, role: "lock" },
  ],
  render(c, p) {
    const T = c.theme;
    const t = c.t;
    stage(c, { kind: "soft" });
    const slide = pr(t, 1.5, 2.1, E.ramp);
    const wmInfo = c.mediaInfo(p.wordmark);
    const wmAspect = wmInfo ? wmInfo.w / wmInfo.h : 5;
    // The mark starts big; as the wordmark slides out the lockup shrinks until it fits the safe width.
    const k0 = c.vertical ? 6.2 : 5.2;
    // Sized from the width visible right now, so the half-revealed wordmark never leaves the frame.
    const unitW = BAR_W * 3 + BAR_GAP * 2 + 6.5 + (p.wordmark ? 96 * 0.62 * wmAspect * slide : 0);
    const k = Math.min(k0, (c.safe.w * 0.92) / unitW);
    const markW = (BAR_W * 3 + BAR_GAP * 2) * k;
    const wmH = 96 * k * 0.62;
    const wmW = wmH * wmAspect;
    const gap = 6.5 * k;
    const totalW = markW + gap + wmW;
    const markX = c.cx - markW / 2 + slide * (-(totalW / 2) + markW / 2);
    const base = c.cy + 45 * k;
    for (let i = 0; i < 3; i++) {
      const s = Math.max(0, spring(t - 0.1 - i * 0.12, SPRING.pop));
      // Voice-meter bounce before settling to the logo heights.
      const keys: Key[] = [[0, 0.2], [0.3, 1.25 - i * 0.2], [0.55, 0.55 + i * 0.1], [0.8, 1.1], [1.05, 0.7], [1.35, 1, E.out]];
      const h = HEIGHTS[i] * k * kf(t - i * 0.06, keys) * Math.min(1, s * 1.2);
      const x = markX + i * (BAR_W + BAR_GAP) * k;
      if (h > 0.5) c.rrect(x, base - h, BAR_W * k, h, (BAR_W * k) / 2, p.colors[i] ?? T.fg);
    }
    if (p.wordmark && slide > 0) {
      const wx = markX + markW + gap;
      c.save();
      c.clipRect(wx - 10, base - wmH * 1.6, wmW * slide + 20, wmH * 2.2);
      c.media(p.wordmark, wx - (1 - slide) * 60, base - wmH * 1.05, wmW, wmH, { fit: "contain", key: "wm" });
      c.restore();
    }
    if (p.tagline) {
      const L = c.fit(p.tagline, style(c, c.vertical ? 60 : 50, { fontParam: p.font, weight: 600 }), c.safe.w * 0.9, 150, { maxLines: 2, align: "center" });
      const u = pr(t, 2.2, 3.0, E.out);
      c.drawLayout(L, c.cx - L.width / 2, base + 90 + (1 - u) * 20, { color: alpha(T.fg, 0.75), emColor: T.accent, alpha: u });
    }
  },
});

