import { E, P, alpha, clamp, defineComponent, pr } from "@motioneasy/engine";
import { style, textFx } from "../kit";
import { clipList } from "../demo";

type Props = { media: string[]; stop: number; slam: string; sub: string; font: string };

const STOP = 1.5;

export default defineComponent<Props>({
  id: "scroll-stop",
  name: "Scroll Stop",
  version: "1.0.0",
  group: "scenes",
  category: "hooks",
  description: "A feed flies past in a motion-blurred blur, brakes hard, and stops dead on your clip. Then one word slams over it. The scroll-stopper, literally.",
  tags: ["hook", "feed", "scroll", "pattern interrupt", "motion blur"],
  added: "2026-10-03",
  featured: true,
  theme: { mode: "dark", lighting: 0.4, grain: 0.35, vignette: 0.45 },
  notes: "Put your best frame as the stop card. The slam word should be one or two words.",
  params: {
    media: P.mediaList(clipList(["william", "aisha", "sol", "gereon", "rusita", "mckensie", "jesse", "omar"]), "Feed clips", "any", { min: 3, max: 12 }),
    stop: P.number(8, "Stop on clip #", { min: 1, max: 12, step: 1 }),
    slam: P.text("Wait.", "Slam word", { maxLength: 20 }),
    sub: P.text("Your captions could look like this.", "Subline", { maxLength: 60 }),
    font: P.font("brand", "Typeface"),
  },
  duration: 4.4,
  poster: 0.62,
  sounds: () => [
    { at: 0, sound: "whoosh.whip", gain: 0.6, role: "flick" },
    { at: 0.45, sound: "whoosh.whip", gain: 0.5, seed: 2, role: "flick" },
    { at: 0.9, sound: "whoosh.swipe", gain: 0.45, role: "brake" },
    { at: STOP, sound: "impact.sub", gain: 0.9, role: "stop" },
    { at: STOP + 0.45, sound: "impact.punch", gain: 0.8, role: "slam" },
  ],
  render(c, p) {
    const T = c.theme;
    const t = c.t;
    const media = p.media.length ? p.media : clipList(["omar"]);
    const n = media.length;
    const stopIdx = clamp(Math.round(p.stop) - 1, 0, n - 1);
    c.clear("#0e0e0d");
    const cw = c.vertical ? c.W * 0.86 : c.H * 0.56 * (432 / 600) * 1.2;
    const ch = cw * (600 / 432);
    const gap = 36;
    const pitch = ch + gap;
    // Feed position: many cards of travel, braking into the stop card (expo-out = fast, then hard brake).
    const travel = pitch * (n * 2 + stopIdx);
    const u = pr(t, 0, STOP, E.out);
    const pos = travel * u; // px scrolled
    const speed = (travel * (E.out(Math.min(1, (t + 1 / 120) / STOP)) - E.out(Math.max(0, (t - 1 / 120) / STOP)))) * 60; // px/s
    const stopped = t >= STOP;
    const after = Math.max(0, t - STOP);
    const zoom = stopped ? 1 + 0.08 * E.out(Math.min(1, after / 0.6)) : 1;
    const blur = Math.min(pitch * 0.5, Math.abs(speed) * (1 / 60) * 0.5);
    const strip = c.layer(c.W, c.H, (lc) => {
      // Card k sits at y = cy + k*pitch - pos, for k over the looping feed.
      const first = Math.floor((pos - c.H) / pitch) - 1;
      const last = Math.ceil((pos + c.H) / pitch) + 1;
      for (let k = first; k <= last; k++) {
        const y = c.cy + k * pitch - pos - ch / 2;
        if (y > c.H + 20 || y + ch < -20) continue;
        const m = media[((k % n) + n) % n];
        lc.media(m, c.cx - cw / 2, y, cw, ch, { radius: 34, key: `feed${((k % n) + n) % n}` });
      }
    });
    const sm = blur > 1 ? c.smearLayer(strip, 0, blur) : strip;
    c.with({ x: c.cx, y: c.cy, scale: zoom }, () => c.drawLayer(sm, -c.cx, -c.cy));
    // Flash on the stop.
    if (stopped && after < 0.18) c.rect(0, 0, c.W, c.H, alpha("#FFFFEB", (1 - after / 0.18) * 0.35));
    // Slam word + subline.
    const st = style(c, c.vertical ? 240 : 200, { fontParam: p.font, weight: 800 });
    const L = c.fit(p.slam, st, c.safe.w * 0.92, 320, { maxLines: 1 });
    const at = STOP + 0.45;
    if (t > at - 0.09) {
      const k = clamp((t - (at - 0.09)) / 0.09);
      const a2 = Math.max(0, t - at);
      const sc = t < at ? 1.8 - 0.8 * E.in(k) : 1 + 0.05 * Math.exp(-a2 * 12) * Math.cos(a2 * 30) + a2 * 0.012;
      c.rect(0, 0, c.W, c.H, alpha("#000", 0.28 * Math.min(1, k)));
      textFx(c, L, c.cx, c.cy - (p.sub ? 60 : 0), { scale: sc, blur: t < at ? (1 - k) * 14 : 0, alpha: Math.min(1, k * 2), color: "#FFFFEB", emColor: "#FFFFEB", shadow: { color: alpha("#000", 0.5), blur: 30, y: 8 } });
      if (p.sub) {
        const S = c.fit(p.sub, style(c, c.vertical ? 50 : 42, { weight: 650 }), c.safe.w * 0.9, 140, { maxLines: 2, align: "center" });
        const v = pr(t, at + 0.35, at + 1.0, E.out);
        c.drawLayout(S, c.cx - S.width / 2, c.cy - 60 + L.height / 2 + 70 + (1 - v) * 16, { color: "#FFFFEB", alpha: v, shadow: { color: alpha("#000", 0.6), blur: 18, y: 4 } });
      }
    }
    void T;
  },
});

stat-trio.code:
import { E, P, alpha, defineComponent, pr, spring, SPRING, type SoundCue } from "@motioneasy/engine";
import { stage, style } from "../kit";

type Props = { headline: string; stats: string[]; hero: number; stagger: number; font: string };

const START = 0.7;

const parse = (s: string) => {
  const [num, ...rest] = s.split("|");
  const m = num.trim().match(/^([^\d-]*)(-?[\d,.]+)(.*)$/);
  return { prefix: m?.[1] ?? "", value: m ? Number(m[2].replace(/,/g, "")) : 0, suffix: m?.[3] ?? num, decimals: m && m[2].includes(".") ? m[2].split(".")[1].length : 0, label: rest.join("|").trim() };
};

export default defineComponent<Props>({
  id: "stat-trio",
  name: "Stat Trio",
  version: "1.0.0",
  group: "scenes",
  category: "proof",
  description: "Three proof points as cards that land one after another, numbers counting as they arrive. The hero card is set in ink.",
  tags: ["stats", "proof", "numbers", "cards", "credibility"],
  added: "2026-10-03",
  featured: true,
  theme: { mode: "light", lighting: 0.6, grain: 0.3, vignette: 0.25 },
  notes: "Write stats as 'number|label', e.g. '33|caption looks'. Real numbers only.",
  params: {
    headline: P.text("Small tool. *Big numbers.*", "Headline", { maxLength: 50 }),
    stats: P.list(["33|caption looks", "0|files uploaded to a server", "1|click to switch looks"], "Stats (number|label)", { min: 1, max: 4, maxLength: 50 }),
    hero: P.number(1, "Hero card", { min: 1, max: 4, step: 1 }),
    stagger: P.number(0.55, "Stagger", { min: 0.2, max: 1.2, step: 0.05, unit: "s" }),
    font: P.font("brand", "Typeface"),
  },
  duration: (p) => START + p.stats.length * p.stagger + 1.8,
  poster: 0.85,
  sounds: (p) => {
    const cues: SoundCue[] = [{ at: 0.1, sound: "whoosh.air", gain: 0.4, role: "headline" }];
    p.stats.forEach((_, i) => {
      cues.push({ at: START + i * p.stagger, sound: "impact.land", gain: 0.45, seed: i + 1, role: "card" });
      cues.push({ at: START + i * p.stagger + 0.75, sound: "ui.tick", gain: 0.4, seed: i + 1, role: "count" });
    });
    return cues;
  },
  render(c, p) {
    const T = c.theme;
    const t = c.t;
    stage(c, { kind: "soft" });
    const V = c.vertical;
    const n = p.stats.length;
    const stats = p.stats.map(parse);
    const H = p.headline ? c.fit(p.headline, style(c, V ? 96 : 78, { fontParam: p.font, weight: 750 }), c.safe.w * 0.92, 220, { maxLines: 2, align: "center" }) : null;
    const gap = 28;
    const cols = V ? 1 : n;
    const cw = V ? c.safe.w : (c.safe.w - gap * (n - 1)) / n;
    const chh = V ? Math.min(290, (c.safe.h - (H ? H.height + 100 : 0) - gap * (n - 1)) / n) : c.H * 0.42;
    const blockH = (H ? H.height + 90 : 0) + (V ? n * chh + (n - 1) * gap : chh);
    const top = c.cy - blockH / 2;
    if (H) {
      const u = pr(t, 0.1, 0.8, E.out);
      c.drawLayout(H, c.cx - H.width / 2, top + (1 - u) * 20, { color: T.fg, emColor: T.accent, alpha: u });
    }
    const y0 = top + (H ? H.height + 90 : 0);
    stats.forEach((s, i) => {
      const at = START + i * p.stagger;
      const k = Math.max(0, spring(t - at, SPRING.firm));
      if (k <= 0) return;
      const hero = i === p.hero - 1;
      const x = V ? c.safe.x : c.safe.x + i * (cw + gap);
      const y = V ? y0 + i * (chh + gap) : y0;
      const bg = hero ? T.fg : T.raised, ink = hero ? T.bg : T.fg;
      c.with({ x: x + cw / 2, y: y + chh / 2 + (1 - Math.min(1, k)) * 60, scale: 0.92 + 0.08 * Math.min(1, k), alpha: Math.min(1, k * 1.5) }, () => {
        c.translate(-(x + cw / 2), -(y + chh / 2));
        c.cardShadow(x, y, cw, chh, 30, hero ? 0.7 : 0.35, hero ? 1.2 : 0.8);
        c.rrect(x, y, cw, chh, 30, bg);
        if (!hero) c.strokeRRect(x + 0.75, y + 0.75, cw - 1.5, chh - 1.5, 30, alpha(T.fg, 0.08), 1.5);
        const v = s.value * pr(t, at + 0.1, at + 0.9, E.out);
        const numStr = `${s.prefix}${v.toFixed(s.decimals).replace(/\B(?=(\d{3})+(?!\d))/g, ",")}${s.suffix}`;
        const nsize = V ? chh * 0.52 : chh * 0.34;
        const N = c.layout(numStr, { font: T.font, size: nsize, weight: 750, tracking: -0.045 });
        // Lay the label out against the final number so it doesn't shift while the count runs.
        const finalStr = `${s.prefix}${s.value.toFixed(s.decimals).replace(/\B(?=(\d{3})+(?!\d))/g, ",")}${s.suffix}`;
        const numW = Math.max(c.layout(finalStr, { font: T.font, size: nsize, weight: 750, tracking: -0.045 }).width, nsize * 1.2);
        const lab = c.fit(s.label, { font: T.font, size: V ? 46 : 42, weight: 600, tracking: -0.015, lineHeight: 1.15 }, V ? cw - numW - 44 * 2 - 34 : cw - 70, chh * 0.5, { maxLines: 2, balance: true });
        if (V) {
          c.drawLayout(N, x + 44, y + chh / 2 - N.cap / 2, { color: ink });
          c.drawLayout(lab, x + 44 + numW + 34, y + chh / 2 - lab.height / 2, { color: hero ? alpha(T.bg, 0.75) : T.soft });
        } else {
          c.drawLayout(N, x + 36, y + 40, { color: ink });
          c.drawLayout(lab, x + 36, y + chh - lab.height - 40, { color: hero ? alpha(T.bg, 0.75) : T.soft });
        }
      });
    });
    void cols;
  },
});

swipe-stack.code:
import { E, P, alpha, clamp, defineComponent, mix, pr, type SoundCue } from "@motioneasy/engine";
import { stage, style } from "../kit";
import { clipList, lookList } from "../demo";

type Props = { media: string[]; labels: string[]; title: string; step: number; radius: number; size: number; font: string };

const START = 0.7;
const FLICK = 0.42;

export default defineComponent<Props>({
  id: "swipe-stack",
  name: "Swipe Stack",
  version: "1.0.0",
  group: "elements",
  category: "media",
  description: "A deck of cards: the top one flicks off-screen with a real motion-blur smear and a twist, the next lifts into place. Like swiping through options, but cinematic.",
  tags: ["cards", "swipe", "deck", "showcase", "motion blur"],
  added: "2026-10-03",
  featured: true,
  theme: { mode: "light", lighting: 0.6, grain: 0.3, vignette: 0.3 },
  notes: "Show variations of one idea (looks, templates, results). 3–6 cards.",
  params: {
    media: P.mediaList(clipList(["gianna", "aisha", "rusita", "william", "sam"]), "Cards", "any", { min: 2, max: 10 }),
    labels: P.list(lookList(["gianna", "aisha", "rusita", "william", "sam"]), "Labels", { max: 10 }),
    title: P.text("Swipe through *every look.*", "Title", { maxLength: 50 }),
    step: P.number(0.95, "Time per card", { min: 0.5, max: 2.5, step: 0.05, unit: "s" }),
    radius: P.number(44, "Corner radius", { min: 0, max: 90, step: 1, group: "style" }),
    size: P.number(1, "Card size", { min: 0.6, max: 1.3, step: 0.05, group: "style" }),
    font: P.font("brand", "Typeface"),
  },
  duration: (p) => START + (p.media.length - 1) * p.step + 1.2,
  poster: 0.3,
  sounds: (p) => {
    const cues: SoundCue[] = [{ at: 0.05, sound: "impact.land", gain: 0.45, role: "deal" }];
    for (let i = 0; i < p.media.length - 1; i++) cues.push({ at: START + i * p.step, sound: "whoosh.swipe", gain: 0.6, seed: (i % 2) + 1, role: "flick" });
    return cues;
  },
  render(c, p) {
    const T = c.theme;
    const t = c.t;
    const media = p.media.length ? p.media : clipList(["gianna"]);
    const n = media.length;
    const V = c.vertical;
    const cw = (V ? 640 : c.landscape ? 420 : 500) * p.size, ch = cw * (600 / 432);
    const cy = c.cy + (p.title ? (V ? 120 : 60) : 0);
    stage(c, { kind: "studio", focus: [c.cx, cy] });
    if (p.title) {
      const L = c.fit(p.title, style(c, V ? 92 : 76, { fontParam: p.font, weight: 750 }), c.safe.w * 0.92, 130, { maxLines: 1 });
      const u = pr(t, 0.1, 0.8, E.out);
      c.drawLayout(L, c.cx - L.width / 2, cy - ch / 2 - L.height - (V ? 80 : 50) + (1 - u) * 20, { color: T.fg, emColor: T.accent, alpha: u });
    }
    const intro = pr(t, 0, 0.6, E.out);
    // How many cards have been flicked away (continuous).
    let gone = 0;
    for (let i = 0; i < n - 1; i++) gone += pr(t, START + i * p.step, START + i * p.step + FLICK, E.in);
    for (let i = n - 1; i >= Math.floor(gone); i--) {
      const depth = i - gone; // 0 = top card
      if (depth > 3.2) continue;
      const flick = clamp(gone - i); // 0..1 for the card leaving
      const dir = i % 2 ? 1 : -1;
      const lift = clamp(1 - depth);
      const k = Math.max(0, depth);
      let x = c.cx + (i % 3 - 1) * 10 * k;
      let y = cy + k * 34 + (1 - intro) * 300;
      let rot = (i % 2 ? 1 : -1) * k * 2.5;
      let scale = 1 - k * 0.05;
      if (flick > 0) {
        x += dir * flick * c.W * 1.05;
        y -= flick * 120;
        rot += dir * flick * 22;
        scale *= 1 + flick * 0.05;
      }
      const card = c.layer(cw, ch, (lc) => {
        lc.media(media[i], 0, 0, cw, ch, { radius: p.radius, key: `ss${i}` });
        lc.save();
        lc.clipRRect(0, 0, cw, ch, p.radius);
        lc.rect(0, 0, cw, ch, lc.linear(0, 0, 0, ch, [[0, alpha("#FFFFFF", 0.1)], [0.4, alpha("#FFFFFF", 0)], [1, alpha("#000000", 0.12)]]));
        if (k > 0.05) lc.rect(0, 0, cw, ch, alpha(T.bg, Math.min(0.35, k * 0.14)));
        lc.restore();
        lc.strokeRRect(0.75, 0.75, cw - 1.5, ch - 1.5, p.radius, alpha("#FFFFFF", 0.45), 1.5);
      }, { pad: 4 });
      // Motion blur proportional to flick speed.
      const v = Math.sin(Math.PI * flick);
      const sm = flick > 0 ? c.smearLayer(card, dir * v * 180, -v * 30) : card;
      c.with({ x, y, rotate: rot, scale }, () => {
        if (flick < 0.6) c.cardShadow(-cw / 2, -ch / 2, cw, ch, p.radius, 0.3 + lift * 0.5, 0.9 * (1 - flick));
        c.drawLayer(sm, -cw / 2, -ch / 2);
      });
    }
    if (p.labels.length) {
      for (let i = 0; i < n; i++) {
        const d = i - gone;
        const a = clamp(1 - Math.abs(d) * 2.4) * intro;
        if (a <= 0 || !p.labels[i]) continue;
        const L = c.layout(p.labels[i], { font: T.mono, size: V ? 34 : 28, weight: 500, tracking: 0.12, uppercase: true });
        c.drawLayout(L, c.cx - L.width / 2 + d * 60, cy + ch / 2 + (V ? 110 : 70), { color: T.soft, alpha: a });
      }
    }
    void mix;
  },
});

terminal-type.code:
import { E, P, alpha, defineComponent, pr, rand, type SoundCue } from "@motioneasy/engine";
import { stage } from "../kit";

type Props = { lines: string; cps: number; window: boolean; title: string; caret: "block" | "bar"; size: number; mistake: boolean; hold: number };

interface Key {
  t: number;
  line: number;
  text: string; // text of that line after this key
  kind: "char" | "back" | "enter";
}

/** Deterministic typing timeline: human rhythm from a seeded generator, pauses on punctuation. */
function plan(p: Props): { keys: Key[]; end: number } {
  const lines = p.lines.replace(/\r/g, "").split("\n");
  const keys: Key[] = [];
  let t = 0.6;
  const base = 1 / Math.max(4, p.cps);
  let seed = 11;
  lines.forEach((line, li) => {
    let cur = "";
    const isCmd = line.startsWith(">") || line.startsWith("$");
    const typed = isCmd ? line : line;
    // Output lines (not commands) print instantly, like a real terminal.
    if (!isCmd && li > 0) {
      t += 0.25;
      keys.push({ t, line: li, text: line, kind: "enter" });
      t += 0.12;
      return;
    }
    const mistakeAt = p.mistake && li === 0 ? Math.floor(typed.length * 0.55) : -1;
    for (let i = 0; i < typed.length; i++) {
      const ch = typed[i];
      if (i === mistakeAt) {
        // wrong key, a beat, backspace
        cur += "x";
        keys.push({ t, line: li, text: cur, kind: "char" });
        t += base * 4;
        cur = cur.slice(0, -1);
        keys.push({ t, line: li, text: cur, kind: "back" });
        t += base * 2;
      }
      cur += ch;
      keys.push({ t, line: li, text: cur, kind: "char" });
      const jitter = 0.55 + rand(seed++) * 0.9;
      t += base * jitter * (/[ ,.]/.test(ch) ? 1.6 : 1);
    }
    t += 0.3;
    keys.push({ t, line: li, text: cur, kind: "enter" });
    t += 0.15;
  });
  return { keys, end: t };
}

export default defineComponent<Props>({
  id: "terminal-type",
  name: "Terminal Type",
  version: "1.0.0",
  group: "elements",
  category: "text-reveals",
  description: "Commands typed with a human rhythm in a clean terminal window, with a real mistake and backspace, and output that prints instantly.",
  tags: ["typing", "terminal", "developer", "mono", "product"],
  added: "2026-10-03",
  featured: false,
  theme: { mode: "dark", lighting: 0.55, grain: 0.3, vignette: 0.45 },
  notes: "Lines starting with > or $ are typed; other lines print as output. Keep it to 2–4 lines.",
  params: {
    lines: P.text("> captionseasy add clip.mp4\nTranscribing on this device...\nDone. 214 words, every one timed.\n> export --mp4 --srt", "Lines", { multiline: true, maxLength: 240 }),
    cps: P.number(16, "Typing speed", { min: 6, max: 40, step: 1, unit: "chars/s" }),
    window: P.bool(true, "Window frame"),
    title: P.text("zsh", "Window title", { maxLength: 30 }),
    caret: P.select("block", "Caret", ["block", "bar"]),
    size: P.number(1, "Type size", { min: 0.6, max: 1.5, step: 0.05, group: "style" }),
    mistake: P.bool(true, "One typo + backspace"),
    hold: P.number(1.2, "Hold", { min: 0.3, max: 4, step: 0.1, unit: "s" }),
  },
  duration: (p) => plan(p).end + p.hold,
  poster: 0.7,
  sounds: (p) => {
    const cues: SoundCue[] = [{ at: 0.02, sound: "whoosh.air", gain: 0.35, role: "window" }];
    plan(p).keys.forEach((k, i) => {
      if (k.kind === "enter") cues.push({ at: k.t, sound: "foley.key", gain: 0.75, seed: 99, rate: 0.85, role: "return" });
      else cues.push({ at: k.t, sound: "foley.key", gain: 0.42 + rand(i * 7) * 0.2, seed: (i % 5) + 1, role: "key" });
    });
    return cues;
  },
  render(c, p) {
    const T = c.theme;
    const t = c.t;
    const { keys } = plan(p);
    const lines = p.lines.replace(/\r/g, "").split("\n");
    // Current text of each line.
    const shown: (string | null)[] = lines.map(() => null);
    let active = 0;
    let lastKey = -1;
    for (const k of keys) {
      if (k.t > t) break;
      shown[k.line] = k.text;
      active = k.kind === "enter" ? Math.min(lines.length - 1, k.line + 1) : k.line;
      lastKey = k.t;
    }
    stage(c, { kind: "soft" });
    const size = Math.min((c.vertical ? 50 : 44) * p.size, (c.safe.w - 120) / Math.max(10, ...p.lines.split("\n").map((l) => l.length)) / 0.6);
    const mono = T.mono;
    const lh = size * 1.6;
    const longest = Math.max(...lines.map((l) => c.layout(l || " ", { font: mono, size, weight: 500, tracking: 0 }).width));
    const pad = size * 1.3;
    const w = Math.min(c.safe.w, Math.max(longest + pad * 2, c.safe.w * 0.7));
    const bar = p.window ? size * 1.6 : 0;
    const h = bar + pad * 2 + lines.length * lh;
    const x = c.cx - w / 2, y = c.cy - h / 2;
    const intro = pr(t, 0, 0.6, E.out);
    const push = 1 + 0.03 * E.cine(c.p);
    c.with({ x: c.cx, y: c.cy + (1 - intro) * 60, scale: push * (0.96 + 0.04 * intro), alpha: intro }, () => {
      c.translate(-c.cx, -c.cy);
      if (p.window) {
        const dark = T.mode === "dark";
        c.cardShadow(x, y, w, h, 22, 0.7, dark ? 2 : 1);
        c.rrect(x, y, w, h, 22, dark ? "#121211" : "#FFFFF6");
        c.strokeRRect(x + 0.75, y + 0.75, w - 1.5, h - 1.5, 22, alpha(T.fg, 0.1), 1.5);
        c.line(x, y + bar, x + w, y + bar, alpha(T.fg, 0.08), 1.5);
        [0, 1, 2].forEach((i) => c.circle(x + size * 0.9 + i * size * 0.75, y + bar / 2, size * 0.2, alpha(T.fg, 0.2)));
        if (p.title) {
          const TL = c.layout(p.title, { font: mono, size: size * 0.62, weight: 500, tracking: 0.04 });
          c.drawLayout(TL, c.cx - TL.width / 2, y + bar / 2 - TL.cap / 2, { color: alpha(T.fg, 0.45) });
        }
      }
      lines.forEach((line, i) => {
        const txt = shown[i];
        if (txt === null) return;
        const isCmd = line.startsWith(">") || line.startsWith("$");
        const ty = y + bar + pad + i * lh;
        const L = c.layout(txt || " ", { font: mono, size, weight: isCmd ? 600 : 400, tracking: 0 });
        c.drawLayout(L, x + pad, ty, { color: isCmd ? T.fg : alpha(T.fg, 0.55) });
        if (i === active) {
          const idle = t - lastKey > 0.35;
          const on = !idle || Math.floor((t - lastKey) * 2.2) % 2 === 0;
          if (on) {
            const cx = x + pad + (txt ? L.width + size * 0.08 : 0);
            if (p.caret === "block") c.rect(cx, ty - size * 0.1, size * 0.58, size * 1.12, alpha(T.fg, 0.85));
            else c.rect(cx, ty - size * 0.12, size * 0.1, size * 1.16, T.fg);
          }
        }
      });
    });
  },
});

